198	/** @brief 创建目录，EEXIST 视为成功。 */
199	static int bringup_mkdir(const char *path)
200	{
201	  clock_t t0;
202	  uint32_t ms;
203	  int ret;
204	  int err = 0;
205	
206	  syslog(LOG_INFO, "INFO: mkdir %s ...\n", path);
207	  t0 = clock_systime_ticks();
208	  myvendor_watchdog_busy_pump();
209	  ret = mkdir(path, 0755);
210	  if (ret < 0)
211	    {
212	      err = errno;
213	    }
214	
215	  ms = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);
216	  syslog(LOG_INFO, "INFO: mkdir %s ret=%d errno=%d %ums\n",
217	         path, ret, err, (unsigned)ms);
218	
219	  if (ret < 0 && err != EEXIST)
220	    {
221	      serr("WARN: mkdir %s failed: %d\n", path, err);
222	      return -err;
223	    }
224	
225	  return OK;
226	}
