407	/* 判"这具僵尸**永远不会再被调度**"。
408	 *
409	 * 为什么需要单独判：上面的 `kill(pid, 0)` 对"活着但卡住"和"再也跑不起来"
410	 * 是同一个答案（都为真），而这两种在恢复策略上完全不同 —— 前者要等它自己
411	 * 退，后者等下去是白等。
412	 *
413	 * 现场依据（2026-09-23）：三连杀 + LCPU 复位连做 28 轮都没收回来，日志停在
414	 * `stuck … BLE down until it exits (check sys hr, or power cycle)`，也就是
415	 * **只能断电**；而那一次的 stall dump 里僵尸的栈只有一帧
416	 * `#0 nxtask_activate`（`task_activate.c:106`，就在 `nxsched_add_readytorun`
417	 * 那一段）⇒ 线程**建起来了但没被调度**，与 GNSS 读线程"被调度器丢掉"同一形状。
418	 *
419	 * 判据（与 myvendor_gnss.c 的 `gnss_reader_lost()` 同源，那次已实机验证）：
420	 *   状态是 RUNNING/READY + **没有 waitobj / waitdog / lockcount** +
421	 *   **不在 `this_task()` 起头的就绪链上** ⇒ 没有任何 waitlist 持有它，
422	 *   没有任何事件能把它挂回就绪链 ⇒ 它永远不会再运行，也就永远不会再碰 HCI。
423	 * 因此隔离它是安全的：TCB/栈留着（泄漏），但不会再与新 companion 抢控制器。
424	 *
425	 * 整段在 `sched_lock()` 里做：既拿到稳定的链快照，也保证"判完"到调用方
426	 * 动手之间没人把它挂回去。 */
427	static bool ble_companion_task_lost(pid_t pid)
428	{
429	  FAR struct tcb_s *tcb;
430	  bool lost = false;
431	
432	  if (pid <= 0)
433	    {
434	      return false;
435	    }
436	
437	  sched_lock();
438	  tcb = nxsched_get_tcb(pid);   /* 必须与 put 成对 */
439	  if (tcb != NULL && tcb->pid == pid &&
440	      (tcb->task_state == TSTATE_TASK_RUNNING ||
441	       tcb->task_state == TSTATE_TASK_READYTORUN) &&
442	      tcb->waitobj == NULL && tcb->lockcount == 0 &&
443	      !WDOG_ISACTIVE(&tcb->waitdog))
444	    {
445	      FAR struct tcb_s *t = this_task();
446	      int hops;
447	
448	      lost = true;   /* 先假设丢了；在链上就翻案 */
449	      for (hops = 0; t != NULL && hops < 64; hops++, t = t->flink)
450	        {
451	          if (t == tcb)
452	            {
453	              lost = false;
454	              break;
455	            }
456	        }
457	    }
458	
459	  if (tcb != NULL)
460	    {
461	      nxsched_put_tcb(tcb);
462	    }
463	
464	  sched_unlock();
465	  return lost;
466	}
