478	/** @brief 等 companion 退出；仍活着则禁止复用 g_ble_companion_stack。 */
479	static int ble_companion_wait_gone(pid_t pid, unsigned wait_ms)
480	{
481	  unsigned steps;
482	  unsigned i;
483	
484	  if (pid <= 0)
485	    {
486	      return 0;
487	    }
488	
489	  steps = (wait_ms + 99u) / 100u;
490	  for (i = 0; i < steps; i++)
491	    {
492	      if (!ble_companion_pid_alive(pid))
493	        {
494	          return 0;
495	        }
496	
497	      usleep(100 * 1000);
498	    }
499	
500	  return ble_companion_pid_alive(pid) ? -ETIMEDOUT : 0;
501	}
