541	#ifdef CONFIG_SCHED_LPWORK
542	/* 杀任务前先摘掉它的 waitdog：**兜底**，不是唯一防线。
543	 *
544	 * 事实核对（2026-09-18 读码）：`nxtask_exithook()` 里的 `nxtask_recover()` 会
545	 * `wd_cancel(&tcb->waitdog)`（`sched/task/task_recover.c:75`，`task_exithook.c:459`），
546	 * 而 exithook 是正常退出和 `nxtask_terminate` 的共同尾巴 —— 也就是说"任务被杀"
547	 * 这条路上，waitdog 本来就会被撤掉。所以这里不是补"没人撤"的洞，而是覆盖
548	 * **退出钩子跑不到的那些情形**：kill 被延迟取消、目标卡在不可中断等待里、
549	 * 或者 TCB 已经被释放/复用而节点还留在 `g_wdactivelist` 上。
550	 *
551	 * 那个形状的后果就是 `vela_override/sched/wd_start.c` 头注释记的
552	 * `pos->prev==NULL` / `curr==NULL` 写 0x7d5（n004/n005）——链上留着指向
553	 * 已复用内存的节点，插链时写飞。先撤再杀的顺序也让现场更好读：日志里
554	 * `cancelled stale waitdog` 出现一次，就说明目标当时**正武装着**。
555	 *
556	 * 注：底层那个 `wd_cancel` 在本 port 上依赖 `vela_override/sched/wd_cancel.c`
557	 * （上游对已摘链的节点仍 `list_delete`）。
558	 *
559	 * 注：本函数放在 `board_restart_ble_companion()` 之前，且**不在任何 #ifdef 内**。 */
560	void myvendor_task_cancel_waitdog(pid_t pid, const char *tag)
561	{
562	  FAR struct tcb_s *tcb;
563	
564	  if (pid <= 0)
565	    {
566	      return;
567	    }
568	
569	  /* 需要成对：nxsched_put_tcb 会把 TCB 引用计数还回去。 */
570	  tcb = nxsched_get_tcb(pid);
571	  if (tcb == NULL)
572	    {
573	      return;
574	    }
575	
576	  if (WDOG_ISACTIVE(&tcb->waitdog))
577	    {
578	      (void)wd_cancel(&tcb->waitdog);
579	      syslog(LOG_WARNING,
580	             "%s: cancelled stale waitdog pid=%d before kill\n",
581	             (tag != NULL) ? tag : "task", (int)pid);
582	    }
583	
584	  nxsched_put_tcb(tcb);
585	}
