625	             "WARN: ble_companion defer queue failed %d, spawn now\n", ret);
626	      board_start_ble_companion_async();
627	    }
628	  else
629	    {
630	      syslog(LOG_INFO, "INFO: ble_companion in 1.5s after UI\n");
631	    }
632	#else
633	  g_ble_start_requested = true;
634	  board_start_ble_companion_async();
