638	int board_restart_ble_companion(void)
639	{
640	  pid_t pid;
641	
642	  if (g_ble_companion_spawning || g_ble_companion_restarting)
643	    {
644	      syslog(LOG_WARNING, "ble_companion: restart busy\n");
645	      return -EBUSY;
646	    }
647	
648	  g_ble_companion_restarting = true;
649	  pid = g_ble_companion_pid;
650	  BLE_LOG("restart begin pid=%d spawn=%d",
651	          (int)pid, g_ble_companion_spawning ? 1 : 0);
652	
653	  if (ble_companion_pid_alive(pid))
654	    {
655	      syslog(LOG_ERR, "ble_companion: stall dump pid=%d phase=%s\n",
656	             (int)pid,
657	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
658	             companion_bridge_phase_get()
659	#else
660	             "-"
661	#endif
662	             );
663	#ifdef CONFIG_BLUETOOTH
664	      sf32lb52_bt_hci_dump_stall();
665	#endif
666	#ifdef CONFIG_SCHED_BACKTRACE
667	      sched_dumpstack(pid);
668	#endif
669	    }
670	
671	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
672	  companion_bridge_teardown_skip_hci_set(true);
673	#endif
674	#ifdef CONFIG_BLUETOOTH
675	  /* 先让 HCI 轮询到 skip：LCPU 复位成功也不要清 skip，
676	   * 否则 companion 仍堵在不可中断等待里会再发同步命令。 */
677	  sf32lb52_bt_hci_skip_sync_set(true);
678	#endif
679	
680	  if (ble_companion_pid_alive(pid))
681	    {
682	      ble_companion_cancel_waitdog(pid);
683	      syslog(LOG_WARNING, "ble_companion: SIGTERM pid=%d\n", (int)pid);
684	      (void)kill(pid, SIGTERM);
685	      if (ble_companion_wait_gone(pid, 1500u) != 0)
686	        {
687	          syslog(LOG_ERR, "ble_companion: SIGKILL pid=%d\n", (int)pid);
688	          (void)kill(pid, SIGKILL);
689	          (void)ble_companion_wait_gone(pid, 500u);
690	        }
691	
692	      if (ble_companion_pid_alive(pid))
693	        {
694	          syslog(LOG_ERR, "ble_companion: task_delete pid=%d\n", (int)pid);
695	          (void)task_delete(pid);
696	          (void)ble_companion_wait_gone(pid, 1000u);
697	        }
698	    }
699	
700	  if (ble_companion_pid_alive(pid) ||
701	      ble_companion_pid_alive(g_ble_companion_pid))
702	    {
703	      g_ble_companion_stuck_n++;
704	      syslog(LOG_ERR,
705	             "ble_companion: still alive pid=%d, skip respawn (attempt %u)\n",
706	             (int)(g_ble_companion_pid > 0 ? g_ble_companion_pid : pid),
707	             (unsigned)g_ble_companion_stuck_n);
708	      BLE_LOG("restart abort still-alive keep skip_sync attempt=%u",
709	              (unsigned)g_ble_companion_stuck_n);
710	
711	      /** ② 收不回来也要把控制器拉起来。
712	       *
713	       *  下面的 `force reset` 只在「杀干净」那条路上（本函数末尾），僵尸
714	       *  不退就永远走不到 —— 现场就是 LCPU 停在哑巴状态、`skip=1`、BLE
715	       *  直到重启都回不来（见 docs/gnss_ble_diag_log.md §2.8）。
716	       *
717	       *  僵尸九成卡在 `net_buf_alloc` / HCI 命令等待这类不可中断等待上，
718	       *  而它等的 buffer 恰恰要靠控制器把 Number Of Completed Packets 送
719	       *  回来才归还。所以「把 LCPU 拉起来」是唯一能让它拿到 buffer、走回
720	       *  取消点、自己退出的动作 —— `nxnotify_cancellation()` 早把 pending
721	       *  cancel 挂在它身上了。拉不起来也只是维持现状，不会更坏。
722	       *
723	       *  force_reset 内部自己会置 skip、按调用前的值还回去（本路径由上面
724	       *  置过，所以保持），不需要在这里再动 skip。
725	       */
726	      syslog(LOG_ERR,
727	             "ble_companion: zombie pid=%d not reapable, reset LCPU to unblock\n",
728	             (int)(g_ble_companion_pid > 0 ? g_ble_companion_pid : pid));
729	#ifdef CONFIG_BLUETOOTH
730	      (void)sf32lb52_bt_controller_force_reset();
731	#endif
732	
733	      /** ③ 连试 N 轮都收不回来，就别再把 HCI 发送路径关着。
734	       *
735	       *  `skip_sync` 是在三连杀之前置的，作用是让僵尸手里的 HCI 命令等待
736	       *  能退出（patch_hci_core.py 的轮询判据）。但僵尸要是永远不退，它就
737	       *  一直留着 —— `host_send()` 对一切命令返回 -ENODEV，连 ble_sensor
738	       *  重连、手机重连这些**跟 companion 无关**的通路也一起废掉，把
739	       *  「companion 挂了」升级成「整块 BLE 挂了」。
740	       *
741	       *  判定不可恢复之后撤回它：僵尸该卡还是卡（它卡的不是这个），但
742	       *  剩下的通路还能自己救回来。回收循环继续重试三连杀，也继续每轮
743	       *  force reset，僵尸真退出的那一轮照样能 spawn（成功路径会把 skip
744	       *  清掉，这里提前清只是不让它挡住别人）。
745	       */
746	      if (g_ble_companion_stuck_n >= BLE_COMPANION_GIVEUP_SKIP_N)
747	        {
748	#ifdef CONFIG_BLUETOOTH
749	          if (sf32lb52_bt_hci_skip_sync())
750	            {
751	              syslog(LOG_ERR,
752	                     "ble_companion: %u attempts, release skip_sync so the "
753	                     "rest of BLE can recover\n",
754	                     (unsigned)g_ble_companion_stuck_n);
755	              sf32lb52_bt_hci_skip_sync_set(false);
756	            }
757	#endif
758	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
759	          companion_bridge_teardown_skip_hci_set(false);
760	#endif
761	        }
762	
763	      /** 收不回来的任务不能就此永久放弃。
764	       *
765	       *  僵尸任务卡在**不可中断等待**上时，SIGTERM / SIGKILL / task_delete
766	       *  都要等它回到取消点才生效（与 GNSS 那条"持锁的尸体"同形，见
767	       *  docs/gnss_ble_diag_log.md §2.4）。原先这里是纯 `return -EBUSY`：
768	       *  僵尸不退出 → 下一次调用照样卡在同一处 → BLE 永久停在
769	       *  「skip=1 + 没有 companion」，现场表现就是手机再也搜不到码表。
770	       *
771	       *  这里起一个**独立的小任务**按固定间隔重试，不依赖 diag 那条 20 s
772	       *  路径，也不占 LPWORK（`board_restart_ble_companion()` 自己最多会
773	       *  阻塞 3 s 等三连杀，压在共享工作队列上会连累别人）。
774	       *  每轮重走上面的 SIGTERM/SIGKILL/task_delete，僵尸真退出后下一轮
775	       *  就能 spawn 回来（`stuck_n` 随之归零，回收任务退出）。
776	       */
777	      if (!g_ble_companion_reclaim_up)
778	        {
779	          posix_spawnattr_t attr;
780	          FAR char *argv[] = { NULL };
781	          int rpid;
782	
783	          posix_spawnattr_init(&attr);
784	          attr.priority  = SCHED_PRIORITY_DEFAULT;
785	          attr.stacksize = sizeof(g_ble_companion_reclaim_stack);
786	          posix_spawnattr_setstackaddr(&attr,
787	                                       g_ble_companion_reclaim_stack);
788	
789	          rpid = task_spawn("ble_reclaim", ble_companion_reclaim_main, NULL,
790	                            &attr, argv, NULL);
791	          if (rpid > 0)
792	            {
793	              g_ble_companion_reclaim_up = true;
794	            }
795	          else
796	            {
797	              syslog(LOG_ERR, "ble_companion: reclaim spawn failed: %d\n",
798	                     rpid);
799	            }
800	        }
801	
802	      /* ⭐ 2026-09-23 加：僵尸若"**永远不会再被调度**"，就别再等它退出。
803	       *
804	       * 现场：三连杀 + LCPU 复位连做 28 轮都收不回来，日志停在
805	       * `stuck … BLE down until it exits (check sys hr, or power cycle)`
806	       * —— 也就是**只能断电**才能让蓝牙回来（用户观察到的就是这个）。
807	       * 而那具僵尸的 stall dump 只有一帧 `#0 nxtask_activate`
808	       * （`task_activate.c:106` 就在 `nxsched_add_readytorun` 那段）⇒
809	       * 它是"建起来了但没被调度"，与 GNSS 读线程被调度器丢掉同一形状：
810	       * 不在任何等待队列上，没有任何事件能把它挂回就绪链 ⇒ **它永远不会
811	       * 再运行、也永远不会再碰 HCI**。
812	       *
813	       * 于是这里把它**隔离**（记下 pid、下一轮起不再杀它），落在下面那条
814	       * "杀干净"的成功路径上照常 spawn 新的 companion —— 僵尸的 TCB/栈留着
815	       * （泄漏，但不可达），换来的是**不需要断电**。
816	       *
817	       * ⚠ 自证伪条件（写死在这里，别忘）：这条判据的前提是"不在就绪链上"。
818	       * 若日志里出现**两具 companion 交替说话**（HCI 行里两套 pid 交错，
819	       * 或 `sys hr` 里同时看到两个 companion），说明那具"僵尸"其实还会被
820	       * 调度 ⇒ **撤回本改动**。隔离次数见 `lost_n=`（正常应长期为 0）。 */
821	      {
822	        pid_t zp = (g_ble_companion_pid > 0) ? g_ble_companion_pid : pid;
823	
824	        if (g_ble_companion_stuck_n >= BLE_COMPANION_GIVEUP_SKIP_N &&
825	            ble_companion_task_lost(zp))
826	          {
827	            g_ble_companion_lost_pid = zp;
828	            g_ble_companion_lost_n++;
829	            syslog(LOG_WARNING,
830	                   "ble_companion: zombie pid=%d unreachable (not on any ready "
831	                   "list) -> quarantine + respawn (lost_n=%u)\n",
832	                   (int)zp, (unsigned)g_ble_companion_lost_n);
833	          }
834	        else
835	          {
836	            if ((g_ble_companion_stuck_n % BLE_COMPANION_RETRY_LOG_N) == 0u)
837	              {
838	                syslog(LOG_ERR,
839	                       "ble_companion: stuck pid=%d, %u attempts; BLE down "
840	                       "until it exits (check `sys hr`, or power cycle)\n",
841	                       (int)zp, (unsigned)g_ble_companion_stuck_n);
842	              }
843	
844	            g_ble_companion_restarting = false;
845	            return -EBUSY;
846	          }
847	      }
848	    }
849	
850	  g_ble_companion_pid = (pid_t)-1;
851	  ble_companion_reap_if_dead();
852	#ifdef CONFIG_BLUETOOTH
853	  BLE_LOG("restart lcpu reset then clear skip and spawn");
854	  (void)sf32lb52_bt_controller_force_reset();
855	  sf32lb52_bt_hci_skip_sync_set(false);
856	#endif
857	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
858	  companion_bridge_teardown_skip_hci_set(false);
859	#endif
860	  usleep(100 * 1000);
861	  board_start_ble_companion_async();
862	  g_ble_companion_restarting = false;
