867	/**
868	 * @brief 僵尸 companion 的定期重试（见 `board_restart_ble_companion()` 末尾）。
869	 *
870	 * @details
871	 * 只在「上一具任务收不回来」时被 spawn，一次生命周期里循环重试：
872	 *
873	 *   - 每 `BLE_COMPANION_RETRY_MS` 调一次 `board_restart_ble_companion()`
874	 *     （它会重走 SIGTERM/SIGKILL/task_delete 三连杀并尝试 spawn）；
875	 *   - `g_ble_companion_stuck_n` 归零表示新任务起来了 → 退出；
876	 *   - 退出前清 `g_ble_companion_reclaim_up`，允许下一次卡死时再起一个。
877	 *
878	 * 刻意不放在 LPWORK 上：`board_restart_ble_companion()` 自己最多阻塞 3 s
879	 * 等三连杀，压在共享工作队列上会连累别的延迟工作。也刻意不用 diag 去驱动
880	 * —— diag 那条 20 s 路径本来就在跑，但没有它（或它被 `restarting` 挡掉）时
881	 * 也需要有人重试。
882	 */
883	static int ble_companion_reclaim_main(int argc, FAR char *argv[])
884	{
885	  (void)argc;
886	  (void)argv;
887	
888	  do
889	    {
890	      usleep(BLE_COMPANION_RETRY_MS * 1000u);
891	
892	      syslog(LOG_WARNING, "ble_companion: retry reclaim (attempt %u)\n",
893	             (unsigned)(g_ble_companion_stuck_n + 1u));
894	      (void)board_restart_ble_companion();
895	    }
896	  while (g_ble_companion_stuck_n != 0u);
897	
898	  g_ble_companion_reclaim_up = false;
899	  return 0;
900	}
901	#endif
