1048	/** @brief 注册 RTC 并设置/读取启动时间。 */
1049	static int bringup_rtc(void)
1050	{
1051	#if defined(CONFIG_RTC) && defined(CONFIG_RTC_DRIVER)
1052	  struct rtc_lowerhalf_s *rtclower;
1053	  int ret;
1054	  int rtcfd;
1055	
1056	  rtclower = sf32lb_rtc_lowerhalf();
1057	  if (rtclower == NULL)
1058	    {
1059	      serr("ERROR: Failed to instantiate RTC lower-half\n");
1060	      return -ENOMEM;
1061	    }
1062	
1063	  ret = rtc_initialize(0, rtclower);
1064	  if (ret < 0)
1065	    {
1066	      serr("ERROR: rtc_initialize failed: %d\n", ret);
1067	      return ret;
1068	    }
1069	
1070	  rtcfd = open("/dev/rtc0", O_RDWR);
1071	  if (rtcfd < 0)
1072	    {
1073	      rtcfd = open("/dev/rtc0", O_RDONLY);
1074	    }
1075	
1076	  if (rtcfd < 0)
1077	    {
1078	      serr("ERROR: open /dev/rtc0 failed: %d\n", errno);
1079	    }
1080	  else
1081	    {
1082	      struct rtc_time rt;
1083	      bool trusted = sf32lb_rtc_trust_is_valid();
1084	
1085	      memset(&rt, 0, sizeof(rt));
1086	      if (!trusted)
1087	        {
1088	          rt.tm_year = 100;
1089	          rt.tm_mon  = 0;
1090	          rt.tm_mday = 1;
1091	          if (ioctl(rtcfd, RTC_SET_TIME,
1092	                    (unsigned long)(uintptr_t)&rt) < 0)
1093	            {
1094	              serr("ERROR: RTC_SET_TIME baseline failed: %d\n", errno);
1095	            }
1096	          else
1097	            {
1098	              trusted = true;
1099	            }
1100	        }
1101	
1102	      memset(&rt, 0, sizeof(rt));
1103	      if (ioctl(rtcfd, RTC_RD_TIME, (unsigned long)(uintptr_t)&rt) < 0)
1104	        {
1105	          serr("ERROR: RTC_RD_TIME failed: %d\n", errno);
1106	        }
1107	      else
1108	        {
1109	          syslog(LOG_WARNING,
1110	                 "[rtc] boot %04d-%02d-%02d %02d:%02d:%02d trusted=%d "
1111	                 "(magic=0x%08x; use 'test rtc' to change)\n",
1112	                 rt.tm_year + 1900, rt.tm_mon + 1, rt.tm_mday,
1113	                 rt.tm_hour, rt.tm_min, rt.tm_sec,
1114	                 trusted ? 1 : 0, SF32LB_RTC_TRUST_MAGIC);
1115	        }
1116	
1117	      close(rtcfd);
1118	    }
1119	#endif
1120	
1121	  return OK;
1122	}
