1551	/** @brief 初始化 I2C1 并注册板载传感器。 */
1552	static int bringup_i2c(void)
1553	{
1554	#ifdef CONFIG_I2C
1555	  struct i2c_master_s *i2c0;
1556	  int ret;
1557	
1558	  BRINGUP_LOG("I2C1 pinmux PA39 SCL / PA38 SDA\n");
1559	  HAL_PIN_Set(PAD_PA39, I2C1_SCL, PIN_PULLUP, 1);
1560	  HAL_PIN_Set(PAD_PA38, I2C1_SDA, PIN_PULLUP, 1);
1561	
1562	  i2c0 = sifli_i2cbus_initialize(0);
1563	  if (i2c0 == NULL)
1564	    {
1565	      syslog(LOG_ERR, "ERROR: sifli_i2cbus_initialize(0) failed\n");
1566	      return -ENODEV;
1567	    }
1568	
1569	  ret = i2c_register(i2c0, 0);
1570	  if (ret < 0)
1571	    {
1572	      syslog(LOG_ERR, "ERROR: i2c_register(/dev/i2c0) failed: %d\n", ret);
1573	      return ret;
1574	    }
1575	
1576	#ifdef CONFIG_BOARD_BMI270
1577	  {
1578	    int attempt;
1579	
1580	    /* Probe IMU first. Missing baro/mag can NACK or hang 5s and must not
1581	     * delay or tear down BMI270. */
1582	    for (attempt = 0; attempt < 3; attempt++)
1583	      {
1584	        ret = sf32lb52_bmi270_register(0, i2c0, CONFIG_BOARD_BMI270_I2C_ADDR);
1585	        if (ret == 0)
1586	          {
1587	            break;
1588	          }
1589	
1590	        syslog(LOG_ERR,
1591	               "ERROR: sf32lb52_bmi270_register failed: %d (try %d/3)\n",
1592	               ret, attempt + 1);
1593	        usleep(200000);
1594	      }
1595	  }
1596	#endif
1597	
1598	#ifdef CONFIG_BOARD_BMP388
1599	  ret = bmp388_register(0, i2c0);
1600	  if (ret < 0)
1601	    {
1602	      syslog(LOG_WARNING,
1603	             "WARN: bmp388 absent (register %d), IMU still used\n", ret);
1604	    }
1605	#endif
1606	
1607	#ifdef CONFIG_BOARD_MMC5983MA
1608	  ret = mmc5983ma_register(0, i2c0);
1609	  if (ret < 0)
1610	    {
1611	      syslog(LOG_WARNING,
1612	             "WARN: mmc5983 absent (register %d), IMU still used\n", ret);
1613	    }
1614	#endif
1615	
1616	  BRINGUP_LOG("I2C sensor bringup complete\n");
1617	#endif
1618	
1619	  return OK;
1620	}
