1812	/**
1813	 * @brief 开机步骤表（顺序即执行顺序）。
1814	 *
1815	 * watchdog 最先：注册 /dev/watchdog0 并 START（接管 2SFBL 留下的 IWDT）。
1816	 * lcd 在 gpio/pwm 之后异步初始化；bicycle 等 storage+devctl。
1817	 * GNSS / I2C 非首帧必需。BLE HCI 只注册设备；companion 等 UI 起来再 spawn。
1818	 */
1819	static const struct bringup_step_s g_bringup[] =
1820	{
1821	  { "watchdog",  bringup_watchdog,  false },
1822	  { "vfs",       bringup_vfs,       false },
1823	  { "rtc",       bringup_rtc,       true  },
1824	  { "adc",       bringup_adc,       true  },
1825	  { "gpio",      bringup_gpio,      true  },
1826	  { "pwm",       bringup_pwm,       true  },
1827	  { "lcd",       bringup_lcd,       false },
1828	  { "cpuload",   bringup_cpuload,   false },
1829	  { "timer",     bringup_timer,     true  },
1830	  { "buttons",   bringup_buttons,   true  },
1831	  { "sound",     bringup_sound,     false },
1832	  { "eta9184",   bringup_eta9184,   false },
1833	  { "storage",   bringup_storage,   false },
1834	  { "devctl",    bringup_devctl,    false },
1835	  { "hclk240",   bringup_hclk240,   false },
1836	  { "clocks",    bringup_clocks,    false },
1837	  { "bicycle",   bringup_bicycle,   false },
1838	  { "gnss_prep", bringup_gnss_prep, false },
1839	  { "gnss",      bringup_gnss,      false },
1840	  { "i2c",       bringup_i2c,       true  },
1841	  { "sensors",   bringup_board_sensor, false },
1842	  { "spi",       bringup_spi,       false },
1843	  { "identity",  bringup_identity,  false },
1844	  { "usbmtp",    bringup_usbmtp,    false },
1845	  { "mtp",       bringup_mtp,       false },
1846	  { "bth4",      bringup_bth4,      false },
1847	  { "ble",       bringup_ble,       false },
1848	  { "diag",      bringup_diag,      false },
1849	};
1850	
1851	/**
1852	 * @brief 按 g_bringup[] 顺序执行板级晚初始化。
1853	 * @return 0 全部完成或仅非 abort 步骤失败；负值为 abort_on_fail 步骤失败码。
1854	 */
1855	int sf32lb52_devkit_lcd_bringup(void)
1856	{
1857	  const size_t n = sizeof(g_bringup) / sizeof(g_bringup[0]);
1858	  size_t i;
1859	  int ret;
1860	
1861	  BRINGUP_LOG("enter, %u steps\n", (unsigned)n);
1862	
1863	  for (i = 0; i < n; i++)
1864	    {
1865	      BRINGUP_LOG("[%u/%u] %s\n",
1866	                  (unsigned)(i + 1), (unsigned)n, g_bringup[i].name);
1867	      myvendor_watchdog_busy_pump();
1868	      ret = g_bringup[i].fn();
1869	      if (ret < 0)
1870	        {
1871	          if (g_bringup[i].abort_on_fail)
1872	            {
1873	              syslog(LOG_ERR, "BRINGUP: %s abort %d\n",
1874	                     g_bringup[i].name, ret);
1875	#ifdef CONFIG_MYVENDOR_WATCHDOG
1876	              myvendor_watchdog_start();
1877	#endif
1878	              return ret;
1879	            }
1880	
1881	          syslog(LOG_WARNING, "BRINGUP: %s fail %d, continue\n",
1882	                 g_bringup[i].name, ret);
1883	        }
1884	    }
1885	
1886	#ifdef CONFIG_MYVENDOR_WATCHDOG
1887	  myvendor_watchdog_start();
1888	#endif
1889	
1890	  BRINGUP_LOG("done\n");
1891	  return OK;
1892	}
