142	/**
143	 * @brief 同上，但**不阻塞**（UI 线程用；锁忙则返回 false 且不改 @p out）。
144	 *
145	 * @details
146	 * 主骑行页的每拍同步会走这条路：BLE 侧（companion / FS 写盘）持着 bridge 锁时，
147	 * UI 线程绝不能陪着等 —— 那会把 LVGL、静止覆盖层心跳、按键和拿起唤醒一起冻住。
148	 */
149	bool myvendor_sys_sensor_get_try(myvendor_sys_sensor_t *out)
150	{
151	  if (out == NULL)
152	    {
153	      return false;
154	    }
155	
156	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
157	  {
158	    struct companion_sensor_telem telem;
159	
160	    if (!companion_bridge_sensor_get_try(&telem))
161	      {
