303	bool myvendor_sys_gnss_eph_busy(void)
304	{
305	  myvendor_sys_gnss_t g;
306	
307	  /* 「星历同步」不能比读线程活得久。
308	   *
309	   * `g_eph_busy` 在注入开始时置位、注入**结束**才清。读线程在注入中途卡死时
310	   * （现场第 4 次：`phase=read-poll`、`busy=1`，diag 每 30 s 重试回收都失败）
311	   * 没人清它 —— 而 UI 判「星历同步」的那一支**排在最前面**，会直接盖掉后面
312	   * 「无数据 / GNSS 失效」的分支。结果屏幕一直显示"星历同步"，而 GNSS 其实
313	   * 已经死了、那个状态永远不会变。这与 BLE 侧那个"粘滞 connected"是同一类毛病：
314	   * 状态标志没有时限、不从事实重新推导。
315	   *
316	   * 这里按**读线程健康**裁掉：只有 HL_OK 才承认"正在同步星历"。判据就在 UI 拿到
317	   * 的那份快照里（`rd_state`，见 myvendor_sys_gnss_health_e），所以这一层不需要
318	   * 额外时基，也不需要读线程配合。 */
319	  if (!myvendor_sys_onboard_gnss_get(&g) ||
320	      g.rd_state != MYVENDOR_SYS_GNSS_HL_OK)
321	    {
322	      return false;
323	    }
324	
325	  return myvendor_gnss_eph_busy();
326	}
