553	/**
554	 * @brief 有符号定点数，不用 %f（NSH 小栈上 dtoa 会打穿）。
555	 *
556	 * @param v      值。
557	 * @param scale  10=一位小数，100=两位。
558	 */
559	static void sys_print_fixed(float v, unsigned scale)
560	{
561	  int neg;
562	  int scaled;
563	  unsigned mag;
564	  unsigned frac;
565	
566	  if (scale != 10u && scale != 100u)
567	    {
568	      scale = 100u;
569	    }
570	
571	  neg = (v < 0.0f);
572	  if (neg)
573	    {
574	      v = -v;
575	    }
576	
577	  scaled = (int)(v * (float)scale + 0.5f);
578	  if (scaled < 0)
579	    {
580	      scaled = 0;
581	    }
582	
583	  mag = (unsigned)scaled;
584	  frac = mag % scale;
585	  mag /= scale;
586	  if (neg && (mag != 0 || frac != 0))
587	    {
588	      putchar('-');
589	    }
590	
591	  if (scale == 100u)
592	    {
593	      printf("%u.%02u", mag, frac);
594	    }
595	  else
596	    {
597	      printf("%u.%u", mag, frac);
598	    }
599	}
