601	/**
602	 * @brief 打印一份 GNSS 快照（板载或手机）的年龄。
603	 *
604	 * @details
605	 * stamp_ms 是本份数据的采样时刻。0 表示来源没给时间戳（未知），此时打 "--"
606	 * 而不是打一个看起来很小的假年龄。消费方必须能区分"刚采到"和"恢复期里
607	 * 被 hold 住的旧值"，否则 sat/age 一起看会得出错误结论。
608	 *
609	 * @param g 快照。
610	 */
611	static void sys_print_gnss_age(const myvendor_sys_gnss_t *g)
612	{
613	  if (g->stamp_ms == 0)
614	    {
615	      printf("  age --");
616	      return;
617	    }
618	
619	  printf("  age %u.%03u s",
620	         (unsigned)(myvendor_mono_elapsed_ms(myvendor_mono_ms(),
621	                                            g->stamp_ms) / 1000u),
622	         (unsigned)(myvendor_mono_elapsed_ms(myvendor_mono_ms(),
623	                                            g->stamp_ms) % 1000u));
624	}
625	
626	void myvendor_sys_gnss_print_pvt(const myvendor_sys_gnss_t *g)
627	{
628	  const char *fix;
629	
630	  if (g == NULL || !g->pvt_valid)
631	    {
632	      return;
633	    }
634	
635	  /* fixType 打成 2D/3D 字样，**不要打数字**：同一行里 `q %u` 是 GGA/GSA 的
636	   * 定位质量（0 无 / 1 2D / 2 3D），PVT 的 fixType 是另一套编号
637	   * （0 无 / 2 2D / 3 3D）—— 两个 "2" 含义相反，数字并排会被读成一致。
638	   * 现场第一次看就撞上了：`q 2`（3D）配 `fix 2`（2D），实际是两边不一致。 */
639	  switch (g->pvt_fix_type)
640	    {
641	      case 2:  fix = "2D"; break;
642	      case 3:  fix = "3D"; break;
643	      case 4:  fix = "DR"; break;
644	      case 5:  fix = "time"; break;
645	      default: fix = "none"; break;
646	    }
647	
648	  /* 单位：gs 与 speed_centi_kmh 同为 0.01 km/h；sacc 是 mm/s，这里打成 m/s
649	   * （两位小数），与 `gnss: pvt` 那行的 mm/s 是同一条数据。 */
650	  printf("  gs %u.%02u km/h  sacc %u.%02u m/s  pvt %s ok %u",
651	         (unsigned)(g->speed_pvt_centi_kmh / 100u),
652	         (unsigned)(g->speed_pvt_centi_kmh % 100u),
653	         (unsigned)(g->speed_acc_mm_s / 1000u),
654	         (unsigned)((g->speed_acc_mm_s % 1000u) / 10u),
655	         fix,
656	         g->pvt_gnss_ok ? 1u : 0u);
657	}
