659	static void sys_print_gnss(const char *name, const myvendor_sys_gnss_t *g)
660	{
661	  if (g->valid)
662	    {
663	      /* lock=解算用星，heard=SNR>0，view=GSV 累加值（不是颗数）。 */
664	      printf("  %-7s %u.%02u km/h  lock %u heard %u view %u  q %u  hdop %u.%u  utc %u",
665	             name,
666	             (unsigned)(g->speed_centi_kmh / 100u),
667	             (unsigned)(g->speed_centi_kmh % 100u),
668	             (unsigned)g->satellites,
669	             (unsigned)g->sats_heard,
670	             (unsigned)g->sats_in_view,
671	             (unsigned)g->fix_quality,
672	             (unsigned)(g->hdop_x10 / 10u),
673	             (unsigned)(g->hdop_x10 % 10u),
674	             (unsigned)g->utc_sec);
675	      myvendor_sys_gnss_print_pvt(g);
676	      sys_print_gnss_age(g);
677	      putchar('\n');
678	    }
679	  else if (g->alive)
680	    {
681	      printf("  %-7s search  lock %u heard %u view %u  hdop %u.%u  utc %u",
682	             name,
683	             (unsigned)g->satellites,
684	             (unsigned)g->sats_heard,
685	             (unsigned)g->sats_in_view,
686	             (unsigned)(g->hdop_x10 / 10u),
687	             (unsigned)(g->hdop_x10 % 10u),
688	             (unsigned)g->utc_sec);
689	      myvendor_sys_gnss_print_pvt(g);
690	      sys_print_gnss_age(g);
691	      putchar('\n');
692	    }
693	  else
694	    {
695	      printf("  %-7s --\n", name);
696	    }
697	}
