733	/**
734	 * @brief 推一个 MPI/FLASH 模块的实际时钟。
735	 *
736	 * @details
737	 * hz = 时钟源 / MPI PSCLR.DIV。PSCLR 是 MPI 的直接整数分频
738	 * （HAL_FLASH_SET_CLK_rom 就是 `PSCLR = div`），而软件分频变量
739	 * BSP_GetFlashxDIV() 只在 HAL_MPI_PSRAM_Init 时被写进硬件、之后可能过期，
740	 * 所以这里以硬件为准，软件值只带出来对照。
741	 *
742	 * @param clk_module RCC_CLK_MOD_FLASH1 / FLASH2。
743	 * @param mpi 该模块的 MPI 实例（hwp_qspi1 / hwp_qspi2）。
744	 * @param sw_div BSP_GetFlashxDIV()，仅用于对照。
745	 * @param hz 输出频率。
746	 * @param src 输出时钟源。
747	 * @param psclr 输出硬件分频。
748	 * @param sw 输出软件分频。
749	 */
750	static void sys_clk_probe_flash(int clk_module, MPI_TypeDef *mpi,
751	                                uint16_t sw_div, uint32_t *hz, uint8_t *src,
752	                                uint8_t *psclr, uint8_t *sw)
753	{
754	  uint32_t base;
755	
756	  *src = (uint8_t)HAL_RCC_HCPU_GetClockSrc(clk_module);
757	  *psclr = (mpi != NULL)
758	               ? (uint8_t)GET_REG_VAL(mpi->PSCLR, MPI_PSCLR_DIV_Msk,
759	                                      MPI_PSCLR_DIV_Pos)
760	               : 0u;
761	  *sw = (uint8_t)(sw_div > 255u ? 255u : sw_div);
762	
763	  base = sys_clk_src_hz(*src);
764	  *hz = base / ((*psclr != 0u) ? *psclr : 1u);
765	}
