767	void myvendor_sys_clk_get(myvendor_sys_clk_t *out)
768	{
769	  if (out == NULL)
770	    {
771	      return;
772	    }
773	
774	  memset(out, 0, sizeof(*out));
775	
776	  out->sysclk_hz = HAL_RCC_GetSysCLKFreq(CORE_ID_HCPU);
777	  out->hclk_hz = HAL_RCC_GetHCLKFreq(CORE_ID_HCPU);
778	
779	  /* DLL 只如实上报使能位与频率，不碰任何配置。 */
780	  if ((hwp_hpsys_rcc->DLL1CR & HPSYS_RCC_DLL1CR_EN) != 0u)
781	    {
782	      out->dll1_en = 1u;
783	      out->dll1_hz = HAL_RCC_HCPU_GetDLL1Freq();
784	    }
785	
786	  if ((hwp_hpsys_rcc->DLL2CR & HPSYS_RCC_DLL2CR_EN) != 0u)
787	    {
788	      out->dll2_en = 1u;
789	      out->dll2_hz = HAL_RCC_HCPU_GetDLL2Freq();
790	    }
791	
792	  sys_clk_probe_flash(RCC_CLK_MOD_FLASH1, hwp_qspi1, BSP_GetFlash1DIV(),
793	                      &out->flash1_hz, &out->flash1_src, &out->flash1_psclr,
794	                      &out->flash1_sw_div);
795	  sys_clk_probe_flash(RCC_CLK_MOD_FLASH2, hwp_qspi2, BSP_GetFlash2DIV(),
796	                      &out->flash2_hz, &out->flash2_src, &out->flash2_psclr,
797	                      &out->flash2_sw_div);
798	
799	  out->mismatch = (out->flash1_psclr != out->flash1_sw_div ||
800	                   out->flash2_psclr != out->flash2_sw_div);
801	}
