826	/** @brief 堆栈摘要：最紧的三个 + 超过 80% 的个数。
827	 *
828	 *  完整表格在 `ps` 里；`sys` 要的是"一眼看出有没有快溢出的任务"，所以只报
829	 *  最紧的三个。占用率用 `up_check_tcbstack()`（染色高水位）算，与 `ps` 的
830	 *  FILLED 同一口径。
831	 */
832	static void sys_print_stacks(void)
833	{
834	  struct row
835	  {
836	    char     name[16];
837	    int      pid;
838	    unsigned used;
839	    unsigned size;
840	    unsigned pct;
841	  };
842	
843	  struct row top[3];
844	  unsigned over80 = 0;
845	  unsigned n = 0;
846	  unsigned i;
847	  int pid;
848	
849	  /* CONFIG_MAX_TASKS 未必定义（这个文件是 NSH app 目标，配置宏不一定齐），
850	   * 给个上界即可 —— pid 是稀疏的小整数，扫一遍花费可忽略。 */
851	#ifndef CONFIG_MAX_TASKS
852	#  define SYS_TASK_SCAN_MAX 128
853	#else
854	#  define SYS_TASK_SCAN_MAX CONFIG_MAX_TASKS
855	#endif
856	
857	  memset(top, 0, sizeof(top));
858	
859	  for (pid = 0; pid < SYS_TASK_SCAN_MAX; pid++)
860	    {
861	      FAR struct tcb_s *tcb = nxsched_get_tcb((pid_t)pid);
862	      unsigned used;
863	      unsigned size;
864	      unsigned pct;
865	
866	      if (tcb == NULL)
867	        {
868	          continue;
869	        }
870	
871	      size = (unsigned)tcb->adj_stack_size;
872	#ifdef CONFIG_STACK_COLORATION
873	      used = (size > 0u) ? (unsigned)up_check_tcbstack(tcb, tcb->adj_stack_size)
874	                         : 0u;
875	#else
876	      used = 0u;
877	#endif
878	      pct = (size > 0u) ? (unsigned)((100u * used) / size) : 0u;
879	      if (pct >= 80u)
880	        {
881	          over80++;
882	        }
883	
884	      for (i = 0; i < 3u; i++)
885	        {
886	          if (pct > top[i].pct)
887	            {
888	              unsigned j;
889	
890	              for (j = 2u; j > i; j--)
891	                {
892	                  top[j] = top[j - 1u];
893	                }
894	
895	              /* 名字要抄出来：put_tcb 之后 TCB 可能已经没了。 */
896	              strncpy(top[i].name, tcb->name, sizeof(top[i].name) - 1u);
897	              top[i].name[sizeof(top[i].name) - 1u] = '\0';
898	              top[i].pid  = (int)tcb->pid;
899	              top[i].used = used;
900	              top[i].size = size;
901	              top[i].pct  = pct;
902	              break;
903	            }
904	        }
905	
906	      n++;
907	      nxsched_put_tcb(tcb);
908	    }
909	
910	  if (n == 0u)
911	    {
912	      return;
913	    }
914	
915	  printf("  stk     %u tasks, %u over 80%%:\n", n, over80);
916	  for (i = 0; i < 3u && top[i].size != 0u; i++)
917	    {
918	      printf("  stk     %-14s %5u/%5u B  %3u%%\n", top[i].name,
919	             top[i].used, top[i].size, top[i].pct);
920	    }
921	}
