126	/**
127	 * @brief 读取当前 HCPU HCLK。
128	 *
129	 * @return 当前 HCLK，单位 MHz；HAL 暂时不可用时返回最近应用值。
130	 */
131	static uint32_t hclk_mhz_now(void)
132	{
133	  uint32_t hz = HAL_RCC_GetHCLKFreq(CORE_ID_HCPU);
134	
135	  if (hz == 0)
136	    {
137	      return g_applied_mhz;
138	    }
139	
140	  return (hz + 500000u) / 1000000u;
141	}
