143	/**
144	 * @brief 判断频率是否为受支持的离散档位。
145	 *
146	 * @param mhz 待检查频率，单位 MHz。
147	 * @return true 表示是 72/96/144/240 MHz 之一，否则返回 false。
148	 */
149	static bool mhz_is_gear(uint32_t mhz)
150	{
151	  unsigned i;
152	
153	  for (i = 0; i < DVFS_NGEAR; i++)
154	    {
155	      if (g_gears[i] == mhz)
156	        {
157	          return true;
158	        }
159	    }
160	
161	  return false;
162	}
163	
164	/**
165	 * @brief 将频率向上取整到最近的受支持档位。
166	 *
167	 * @param mhz 最低需求频率，单位 MHz。
168	 * @return 不低于 @p mhz 的档位；超过最高档时返回 240 MHz。
169	 */
170	static uint32_t gear_ceil(uint32_t mhz)
171	{
172	  unsigned i;
173	
174	  for (i = 0; i < DVFS_NGEAR; i++)
175	    {
176	      if (g_gears[i] >= mhz)
177	        {
178	          return g_gears[i];
179	        }
180	    }
181	
182	  return SF32LB_DVFS_MHZ_240;
183	}
184	
185	/**
186	 * @brief 获取当前档位的相邻低档。
187	 *
188	 * @param mhz 当前档位，单位 MHz。
189	 * @return 相邻低档；输入为最低档时仍返回 72 MHz。
190	 */
191	static uint32_t gear_prev(uint32_t mhz)
192	{
193	  unsigned i;
194	
195	  for (i = 1; i < DVFS_NGEAR; i++)
196	    {
197	      if (g_gears[i] >= mhz)
198	        {
199	          return g_gears[i - 1];
200	        }
201	    }
202	
203	  return g_gears[DVFS_NGEAR - 2];
204	}
205	
206	/**
207	 * @brief 计算无符号 32 位整数的向上整除。
208	 *
209	 * @param num 被除数。
210	 * @param den 除数；为 0 时直接返回 @p num。
211	 * @return 向上取整后的商。
212	 */
213	static uint32_t ceil_div_u32(uint32_t num, uint32_t den)
214	{
215	  if (den == 0)
216	    {
217	      return num;
218	    }
219	
220	  return (num + den - 1u) / den;
221	}
