223	/**
224	 * @brief 获取 PID0 idle 百分比。
225	 *
226	 * @return 0～100 的 idle 百分比；CPU load 不可用时返回 100。
227	 */
228	static uint8_t idle_pct_now(void)
229	{
230	#ifndef CONFIG_SCHED_CPULOAD_NONE
231	  struct cpuload_s load;
232	
233	  if (clock_cpuload(0, &load) == 0 && load.total > 0)
234	    {
235	      return (uint8_t)((100ull * (uint64_t)load.active) /
236	                       (uint64_t)load.total);
237	    }
238	#endif
239	
240	  return 100;
241	}
242	
243	/**
244	 * @brief 以支持 32 位回绕的方式判断当前 tick 是否早于截止 tick。
245	 *
246	 * @param now 当前 tick。
247	 * @param deadline 截止 tick。
248	 * @return 尚未到期返回 true，已到期返回 false。
249	 */
250	static bool tick_before(uint32_t now, uint32_t deadline)
251	{
252	  return (int32_t)(now - deadline) < 0;
253	}
