255	/**
256	 * @brief 清理已经到期的交互 boost。
257	 *
258	 * @note 调用者必须持有 g_lock。
259	 */
260	static void interactive_expire_locked(void)
261	{
262	  if (g_interactive_active &&
263	      !tick_before((uint32_t)clock_systime_ticks(),
264	                   g_interactive_deadline))
265	    {
266	      g_interactive_active = false;
267	    }
268	}
269	
270	/**
271	 * @brief 获取交互频率下限对应的合法档位。
272	 *
273	 * @return 配置值向上取整后的频率档位，单位 MHz。
274	 */
275	static uint32_t interactive_mhz(void)
276	{
277	  return gear_ceil(CONFIG_MYVENDOR_DVFS_INTERACTIVE_MHZ);
278	}
279	
280	/**
281	 * @brief 根据当前 idle 和频率预测合适的目标档位。
282	 *
283	 * @details
284	 * 先计算等效需求 `need = cur * (100 - idle) / 100`。升档使用
285	 * IDLE_UP 预留，降档使用更大的 IDLE_DOWN 预留，从而形成 Schmitt 回差。
286	 *
287	 * @param idle 当前 PID0 idle 百分比。
288	 * @param cur 当前实际 HCLK，单位 MHz。
289	 * @return 按容量预测得到的离散频率档位。
290	 */
291	static uint32_t gov_pick_mhz(uint8_t idle, uint32_t cur)
292	{
293	  uint32_t need;
294	  uint32_t up_min;
295	  uint32_t down_min;
296	  uint32_t busy;
297	
298	  if (cur == 0)
299	    {
300	      cur = SF32LB_DVFS_MHZ_240;
301	    }
302	
303	  if (idle > 100)
304	    {
305	      idle = 100;
306	    }
307	
308	  busy = 100u - (uint32_t)idle;
309	  need = (busy * cur) / 100u;
310	  if (need == 0)
311	    {
312	      need = 1;
313	    }
314	
315	  up_min = ceil_div_u32(need * 100u, 100u - CONFIG_MYVENDOR_DVFS_IDLE_UP);
316	  down_min = ceil_div_u32(need * 100u, 100u - CONFIG_MYVENDOR_DVFS_IDLE_DOWN);
317	
318	  if (cur < up_min)
319	    {
320	      return gear_ceil(up_min);
321	    }
322	
323	  if (cur > down_min)
324	    {
325	      return gear_ceil(down_min);
326	    }
327	
328	  return cur;
329	}
330	
331	/**
332	 * @brief 用最新负载样本更新 governor 档位。
333	 *
334	 * @details
335	 * 升档立即生效；降档必须保持同一候选档达到配置时长，并且每次最多下降一档。
336	 *
337	 * @param idle 最新 PID0 idle 百分比。
338	 * @note 调用者必须持有 g_lock。
339	 */
340	static void gov_update_load_locked(uint8_t idle)
341	{
342	  uint32_t candidate;
343	  uint32_t cur;
344	  uint32_t pick;
345	  clock_t now;
346	
347	  g_idle_pct = idle;
348	  cur = g_applied_mhz ? g_applied_mhz : hclk_mhz_now();
349	  pick = gov_pick_mhz(idle, cur);
350	  now = clock_systime_ticks();
351	
352	  if (pick > g_gov_mhz)
353	    {
354	      g_gov_mhz = pick;
355	      g_down_candidate_mhz = 0;
356	    }
357	  else if (pick < g_gov_mhz)
358	    {
359	      /* Drop at most one gear, and only after the same lower target has
360	       * remained valid for the full hold interval.  This is the down side
361	       * of the Schmitt trigger; transient idle spikes cannot collapse HCLK.
362	       */
363	
364	      candidate = gear_prev(g_gov_mhz);
365	      if (candidate != g_down_candidate_mhz)
366	        {
367	          g_down_candidate_mhz = candidate;
368	          g_down_ticks = now;
369	        }
370	      else if ((clock_t)(now - g_down_ticks) >=
371	               MSEC2TICK(CONFIG_MYVENDOR_DVFS_DOWN_HOLD_MS))
372	        {
373	          g_gov_mhz = candidate;
374	          g_down_candidate_mhz = 0;
375	        }
376	    }
377	  else
378	    {
379	      g_down_candidate_mhz = 0;
380	    }
381	}
382	
383	/**
384	 * @brief 合并 force、强制 hold、负载档位和交互下限。
385	 *
386	 * @return 最终要求应用的 HCLK 档位，单位 MHz。
387	 * @note 调用者必须持有 g_lock。
388	 */
389	static uint32_t target_mhz_locked(void)
390	{
391	  uint32_t target;
392	
393	  if (mhz_is_gear(g_force_mhz))
394	    {
395	      return g_force_mhz;
396	    }
397	
398	  interactive_expire_locked();
399	
400	  if ((g_holds & SF32LB_DVFS_HOLD_FLOOR) != 0)
401	    {
402	      return SF32LB_DVFS_MHZ_240;
403	    }
404	
405	#ifdef CONFIG_SCHED_CPULOAD_NONE
406	  target = g_holds ? SF32LB_DVFS_MHZ_240 : SF32LB_DVFS_MHZ_144;
407	#else
408	  target = g_gov_mhz;
409	#endif
410	
411	  if (g_interactive_active && target < interactive_mhz())
412	    {
413	      target = interactive_mhz();
414	    }
415	
416	  return target;
417	}
