419	/**
420	 * @brief 根据 ETA9184 充电状态维护充电强制高频 hold。
421	 *
422	 * @note 调用者必须持有 g_lock。
423	 */
424	static void charge_hold_locked(void)
425	{
426	  if (eta9184_power_state() == ETA9184_POWER_CHARGING)
427	    {
428	      g_holds |= SF32LB_DVFS_HOLD_CHARGE;
429	    }
430	  else
431	    {
432	      g_holds &= ~SF32LB_DVFS_HOLD_CHARGE;
433	    }
434	}
