436	/**
437	 * @brief HCLK 切换后重配所有依赖 HCLK 的外设。
438	 *
439	 * @details
440	 * 包括 SysTick LOAD（不重启 arch_timer）、SD、LCDC 和背光 PWM。
441	 * 背光已关闭时不会被重新打开。USART 波特率走 SystemFixClock，不在这里
442	 * HAL_UART_Init（会清 DMAR，GNSS 假死）。
443	 */
444	static void reclock_peripherals(void)
445	{
446	  sifli_systick_reclock();
447	  /* SysTick LOAD 变了 → tick 换算失真；先把 WDT 心跳钉到"现在"。 */
448	  myvendor_watchdog_tick_reclock();
449	#ifdef CONFIG_LCD_USING_NV3031A
450	  sf32lb_lcd_reclock();
451	#endif
452	#ifdef CONFIG_MTD
453	  sf32lb_sd_reclock();
454	#endif
455	#ifdef CONFIG_LCD_USING_NV3031A
456	  {
457	    uint8_t pct = BSP_LCD_BL_GetPct();
458	
459	    /* Idle sleep has backlight off; do not turn it back on. */
460	    if (pct > 0)
461	      {
462	        (void)BSP_LCD_BL_PwmPct(pct);
463	      }
464	  }
465	#endif
466	}
