468	/**
469	 * @brief 将仲裁后的目标档位应用到硬件。
470	 *
471	 * @return 0 表示成功或无需切换，-EIO 表示 HAL 切频失败。
472	 * @note 调用者必须持有 g_lock。
473	 */
474	static int apply_locked(void)
475	{
476	  irqstate_t flags;
477	  HAL_StatusTypeDef st;
478	  uint32_t want;
479	  uint32_t dll2;
480	
481	  if (!g_hw_ready)
482	    {
483	      return 0;
484	    }
485	
486	  want = target_mhz_locked();
487	  if (want == g_applied_mhz)
488	    {
489	      return 0;
490	    }
491	
492	  /* HCLK 切换前先把 SD 时钟停掉。SDCLK 是 HCLK 分频出来的，切换瞬间不管
493	   * 分频表怎么算，卡上都会看到一段非预期的时钟；向上跳档（72->240，分频
494	   * 3 -> 10）更是直接给到 80 MHz。同时 reclock_peripherals() 里的
495	   * sf32lb_sd_reclock() 要拿 g_sd_lock，文件系统忙时实测被拖后 4.86 s
496	   * （日志 SD: clk div 240 -> 16 比 hop 晚 4.86 s），这段时间卡一直在跑旧
497	   * 分频。停钟之后这两件事都不再影响卡。
498	   */
499	  sf32lb_sd_clk_hold();
500	
501	  flags = enter_critical_section();
502	  SCB_InvalidateICache();
503	  st = HAL_RCC_HCPU_ConfigHCLK(want);
504	  leave_critical_section(flags);
505	
506	  if (st != HAL_OK)
507	    {
508	      /* 切频失败，但 SDCLK 已经被 clk_hold 停掉了，必须放回去，
509	       * 否则卡就此没有时钟。 */
510	      reclock_peripherals();
511	      syslog(LOG_ERR,
512	             "dvfs: ConfigHCLK(%u) st=%d holds=0x%x idle=%u gov=%u "
513	             "boost=%u dll2=%lu\n",
514	             (unsigned)want, (int)st, (unsigned)g_holds,
515	             (unsigned)g_idle_pct, (unsigned)g_gov_mhz,
516	             (unsigned)(g_interactive_active ? interactive_mhz() : 0),
517	             (unsigned long)HAL_RCC_HCPU_GetDLL2Freq());
518	      return -EIO;
519	    }
520	
521	  g_applied_mhz = want;
522	  reclock_peripherals();
523	  dll2 = HAL_RCC_HCPU_GetDLL2Freq();
524	  syslog(LOG_INFO,
525	         "dvfs: HCLK=%u MHz holds=0x%x force=%u idle=%u gov=%u "
526	         "boost=%u dll2=%lu\n",
527	         (unsigned)g_applied_mhz, (unsigned)g_holds,
528	         (unsigned)g_force_mhz, (unsigned)g_idle_pct,
529	         (unsigned)g_gov_mhz,
530	         (unsigned)(g_interactive_active ? interactive_mhz() : 0),
531	         (unsigned long)dll2);
532	  return 0;
533	}
