535	/**
536	 * @brief 将 hold 位图转换为便于诊断的名称列表。
537	 *
538	 * @param buf 输出缓冲区。
539	 * @param n 输出缓冲区长度。
540	 * @param holds hold 位图。
541	 */
542	static void holds_put(char *buf, size_t n, uint32_t holds)
543	{
544	  size_t used = 0;
545	  unsigned i;
546	  static const struct
547	  {
548	    uint32_t bit;
549	    const char *name;
550	  } names[] =
551	    {
552	      { SF32LB_DVFS_HOLD_BOOT,   "boot" },
553	      { SF32LB_DVFS_HOLD_AWAKE,  "awake" },
554	      { SF32LB_DVFS_HOLD_MAP,    "map" },
555	      { SF32LB_DVFS_HOLD_CHARGE, "charge" },
556	      { SF32LB_DVFS_HOLD_OFFING, "off" },
557	    };
558	
559	  if (n == 0)
560	    {
561	      return;
562	    }
563	
564	  buf[0] = '\0';
565	  if (holds == 0)
566	    {
567	      (void)snprintf(buf, n, "-");
568	      return;
569	    }
570	
571	  for (i = 0; i < sizeof(names) / sizeof(names[0]); i++)
572	    {
573	      int w;
574	
575	      if ((holds & names[i].bit) == 0)
576	        {
577	          continue;
578	        }
579	
580	      w = snprintf(buf + used, n - used, "%s%s",
581	                   used ? "," : "", names[i].name);
582	      if (w < 0 || (size_t)w >= n - used)
583	        {
584	          return;
585	        }
586	
587	      used += (size_t)w;
588	    }
589	}
