591	/**
592	 * @brief 按下标取档位，带显式边界钳制。
593	 *
594	 * @details
595	 * g_hop_pos 只在 [0, DVFS_NGEAR) 内取模推进，但它是跨函数改写的静态量，
596	 * 静态分析无法证明每个使用点的下标都在范围内。跳频的所有档位取值都走这个
597	 * 访问器，越界索引在编译期即可证不存在。
598	 *
599	 * @param pos 档位下标。
600	 * @return 档位频率，单位 MHz。
601	 */
602	static uint32_t gear_at(uint8_t pos)
603	{
604	  if (pos >= (uint8_t)DVFS_NGEAR)
605	    {
606	      pos = 0u;
607	    }
608	
609	  return g_gears[pos];
610	}
611	
612	/**
613	 * @brief 把下标向前推进一格（模 DVFS_NGEAR）。
614	 *
615	 * @param pos 当前下标。
616	 * @param step 步长，必须非 0；取 DVFS_NGEAR 的互质值可遍历全部档位。
617	 * @return 推进后的下标，恒小于 DVFS_NGEAR。
618	 */
619	static uint8_t gear_step(uint8_t pos, uint32_t step)
620	{
621	  uint32_t next = ((uint32_t)pos + step) % (uint32_t)DVFS_NGEAR;
622	
623	  return (uint8_t)next;
624	}
625	
626	/**
627	 * @brief 挑下一个跳频档位：按与档位数互质的步长轮转。
628	 *
629	 * @details
630	 * 这里不做伪随机数。跳频自检的目的是让切频路径（ConfigHCLK + 外设重配）
631	 * 被反复走到，而不是产生不可预测序列，所以用"相邻必不同、每轮遍历全部档位"
632	 * 的轮转更合适：
633	 *   - 步长取 DVFS_NGEAR-1，与档位数恒互质 ⇒ 连续 DVFS_NGEAR 次跳变覆盖
634	 *     全部档位；纯随机可能很久碰不到某个档，覆盖不完整；
635	 *   - 步长非 0 ⇒ 每次跳变都真的换频，不会原地不动白跳一次；
636	 *   - 步长 N-1 让顺序是"跨大步"而不是单调爬升：4 档时依次是
637	 *     72→240→144→96，含 72↔240 这种最大跨度，正是要测的场景；
638	 *   - 起点在 hop_start 时轮换，所以每次自检的档位次序不同，看起来像乱跳。
639	 *
640	 * @param cur 当前 HCLK，单位 MHz，用于兜底保证目标不等于它。
641	 * @return 目标档位，单位 MHz，必定不等于 @p cur。
642	 * @note 调用者必须持有 g_lock。
643	 */
644	static uint32_t hop_pick_locked(uint32_t cur)
645	{
646	  uint32_t pick;
647	
648	  g_hop_pos = gear_step(g_hop_pos, DVFS_NGEAR - 1u);
649	  pick = gear_at(g_hop_pos);
650	
651	  if (pick == cur)
652	    {
653	      /* 只在起点与当前档重合时发生一次，推一格即可。 */
654	      g_hop_pos = gear_step(g_hop_pos, 1u);
655	      pick = gear_at(g_hop_pos);
656	    }
657	
658	  return pick;
659	}
660	
661	/**
662	 * @brief 到点则随机跳一档；走强制通道，hold / governor 全部让路。
663	 *
664	 * @note 调用者必须持有 g_lock。由 gov_worker 每 DVFS_GOV_POLL_MS 驱动。
665	 */
666	static void hop_tick_locked(void)
667	{
668	  uint32_t now;
669	  uint32_t cur;
670	  uint32_t pick;
671	
672	  if (!g_hop_active)
673	    {
674	      return;
675	    }
676	
677	  now = (uint32_t)clock_systime_ticks();
678	  if (g_hop_next_ticks != 0 && (int32_t)(now - g_hop_next_ticks) < 0)
679	    {
680	      return;
681	    }
682	
683	  g_hop_next_ticks = now + (uint32_t)MSEC2TICK(g_hop_period_ms);
684	  cur = g_applied_mhz ? g_applied_mhz : hclk_mhz_now();
685	  pick = hop_pick_locked(cur);
686	  g_force_mhz = pick;
687	  g_hop_n++;
688	  syslog(LOG_WARNING, "dvfs: hop #%u %u -> %u MHz (period %u ms)\n",
689	         (unsigned)g_hop_n, (unsigned)cur, (unsigned)pick,
690	         (unsigned)g_hop_period_ms);
691	  (void)apply_locked();
692	}
693	
694	/**
695	 * @brief LPWORK 周期负载采样与调频入口。
696	 *
697	 * @param arg work queue 参数，当前未使用。
698	 */
699	static void gov_worker(FAR void *arg)
700	{
701	  int ret;
702	
703	  (void)arg;
704	
705	  g_gov_last_ticks = (uint32_t)clock_systime_ticks();
706	  g_gov_runs++;
707	
708	  nxmutex_lock(&g_lock);
709	  if (g_hw_ready)
710	    {
711	      gov_update_load_locked(idle_pct_now());
712	      charge_hold_locked();
713	      hop_tick_locked();
714	      (void)apply_locked();
715	    }
716	
717	  nxmutex_unlock(&g_lock);
718	
719	  ret = work_queue(LPWORK, &g_gov_work, gov_worker, NULL,
720	                   MSEC2TICK(DVFS_GOV_POLL_MS));
721	  if (ret < 0)
722	    {
723	      /* 自愈第一层。work_queue_start() 在重挂前本来就会 work_remove 掉残留的
724	       * 排队状态，所以正常不该失败；真失败（-EINVAL 之类）说明 work_s 或队列
725	       * 本身出了问题。清一次状态重挂，比永久停摆好 —— 停摆意味着 ondemand、
726	       * charge hold、hop 全部一起失效，而且以前完全静默。第二层兜底在 diag
727	       * 线程（它按心跳年龄判定，见 sf32lb_dvfs_gov_kick）。 */
728	      syslog(LOG_ERR, "dvfs: gov re-arm FAILED %d after %lu runs, self-heal retry\n",
729	             ret, (unsigned long)g_gov_runs);
730	
731	      (void)work_cancel(LPWORK, &g_gov_work);
732	      ret = work_queue(LPWORK, &g_gov_work, gov_worker, NULL,
733	                       MSEC2TICK(DVFS_GOV_POLL_MS));
734	      if (ret < 0)
735	        {
736	          syslog(LOG_ERR, "dvfs: gov self-heal FAILED %d; diag must kick\n", ret);
737	        }
738	      else
739	        {
740	          g_gov_recoveries++;
741	        }
742	    }
743	}
744	
745	/**
746	 * @brief 外部恢复：把调频 worker 重新挂上（供 diag 线程心跳超时后调用）。
747	 *
748	 * @details 与 gov_worker 内部的自愈互补：这里是从**另一个线程**动手，所以
749	 *          即使 worker 已经彻底不再运行也能把它接回来。先 work_cancel 摘掉
750	 *          可能的残留排队项再挂，重复挂载会被 work_queue_start 内部合并。
751	 *
752	 * @return 0 已重新挂上；负值为 work_queue 的错误码。
753	 */
754	int sf32lb_dvfs_gov_kick(void)
755	{
756	  int ret;
757	
758	  (void)work_cancel(LPWORK, &g_gov_work);
759	  ret = work_queue(LPWORK, &g_gov_work, gov_worker, NULL,
760	                   MSEC2TICK(DVFS_GOV_POLL_MS));
761	  if (ret == 0)
762	    {
763	      g_gov_recoveries++;
764	      syslog(LOG_WARNING, "dvfs: gov re-armed by diag (recoveries=%lu)\n",
765	             (unsigned long)g_gov_recoveries);
766	    }
767	
768	  return ret;
769	}
770	
771	/**
772	 * @brief 调频 worker 被外部接回来的累计次数。
773	 */
774	uint32_t sf32lb_dvfs_gov_recoveries(void)
775	{
776	  return g_gov_recoveries;
777	}
778	
779	/**
780	 * @brief 调频 worker 心跳，供 `ctl dvfs` / `sys` 判"调频还活着吗"。
781	 */
782	void sf32lb_dvfs_gov_stat(uint32_t *age_ms, uint32_t *runs)
783	{
784	  if (runs != NULL)
785	    {
786	      *runs = g_gov_runs;
787	    }
788	
789	  if (age_ms == NULL)
790	    {
791	      return;
792	    }
793	
794	  if (g_gov_last_ticks == 0)
795	    {
796	      *age_ms = 0xffffffffu;
797	      return;
798	    }
799	
800	  *age_ms = (uint32_t)TICK2MSEC((uint32_t)clock_systime_ticks() - g_gov_last_ticks);
801	}
