877	/**
878	 * @brief 报告用户交互并立即建立短时交互频率下限。
879	 *
880	 * @details
881	 * 连续输入会刷新截止时间和降档计时；force 与 240 MHz floor hold 优先。
882	 */
883	void sf32lb_dvfs_interact(void)
884	{
885	  uint32_t floor;
886	  uint32_t duration;
887	  uint32_t now;
888	
889	  nxmutex_lock(&g_lock);
890	  now = (uint32_t)clock_systime_ticks();
891	  duration = (uint32_t)MSEC2TICK(CONFIG_MYVENDOR_DVFS_INTERACTIVE_MS);
892	  if (duration == 0)
893	    {
894	      duration = 1;
895	    }
896	
897	  g_interactive_deadline = now + duration;
898	  g_interactive_active = true;
899	  floor = interactive_mhz();
900	  if (g_gov_mhz < floor)
901	    {
902	      g_gov_mhz = floor;
903	    }
904	
905	  /* The down hold starts again from the last input edge.  Once interaction
906	   * stops, the governor therefore walks 144 -> 96 -> 72 instead of dropping
907	   * straight back to 72 when the short floor expires.
908	   */
909	
910	  g_down_candidate_mhz = 0;
911	  (void)apply_locked();
912	  nxmutex_unlock(&g_lock);
913	}
914	
915	/**
916	 * @brief 设置或取消调试强制频率。
917	 *
918	 * @param mhz 0 表示恢复自动；其它值必须为支持的离散档位。
919	 * @return 0 表示成功，-EINVAL 表示档位无效，-EIO 表示硬件切换失败。
920	 */
921	int sf32lb_dvfs_force(uint32_t mhz)
922	{
923	  int ret;
924	
925	  if (mhz != 0 && !mhz_is_gear(mhz))
926	    {
927	      return -EINVAL;
928	    }
929	
930	  nxmutex_lock(&g_lock);
931	  /* 显式指定档位即接管控制权：停掉随机跳频，避免下一次跳变把它覆盖掉。 */
932	  if (g_hop_active)
933	    {
934	      g_hop_active = false;
935	      g_hop_next_ticks = 0;
936	      syslog(LOG_WARNING,
937	             "dvfs: hop stop after %u jumps (ctl dvfs %u)\n",
938	             (unsigned)g_hop_n, (unsigned)mhz);
939	    }
940	
941	  g_force_mhz = mhz;
942	  ret = apply_locked();
943	  nxmutex_unlock(&g_lock);
944	  return ret;
945	}
946	
947	int sf32lb_dvfs_hop_start(uint32_t period_ms)
948	{
949	  if (period_ms == 0u)
950	    {
951	      period_ms = SF32LB_DVFS_HOP_DEFAULT_MS;
952	    }
953	
954	  if (period_ms < SF32LB_DVFS_HOP_MIN_MS ||
955	      period_ms > SF32LB_DVFS_HOP_MAX_MS)
956	    {
957	      return -EINVAL;
958	    }
959	
960	  nxmutex_lock(&g_lock);
961	  g_hop_period_ms = period_ms;
962	  g_hop_next_ticks = 0; /* 首次立即跳，便于确认命令生效 */
963	  g_hop_n = 0;
964	  /* 起点按开机时刻轮换：每次启动自检的档位次序不同，但每轮仍覆盖全部档位。 */
965	  g_hop_pos = gear_step(0u, (uint32_t)clock_systime_ticks() / 7u);
966	  g_hop_active = true;
967	  syslog(LOG_WARNING,
968	         "dvfs: hop start period=%u ms start=%u MHz gears=72/96/144/240 "
969	         "(force path)\n",
970	         (unsigned)period_ms, (unsigned)gear_at(g_hop_pos));
971	  hop_tick_locked();
972	  nxmutex_unlock(&g_lock);
973	  return 0;
974	}
975	
976	void sf32lb_dvfs_hop_stop(void)
977	{
978	  nxmutex_lock(&g_lock);
979	  if (g_hop_active)
980	    {
981	      g_hop_active = false;
982	      g_hop_next_ticks = 0;
983	      /* 交还 governor：清掉跳频期间设的强制档，否则会一直钉在最后一档。 */
984	      g_force_mhz = 0;
985	      syslog(LOG_WARNING, "dvfs: hop stop after %u jumps -> auto\n",
986	             (unsigned)g_hop_n);
987	      (void)apply_locked();
988	    }
989	
990	  nxmutex_unlock(&g_lock);
991	}
