253	/** 已就 NULL 缓冲拒绝过一次读取（只报一次，避免刷屏）。 */
254	static bool g_null_read_seen;
255	
256	/**
257	 * @brief 读一个 uORB sensor 节点，入口挡掉 NULL 缓冲。
258	 *
259	 * @details
260	 * 上游 `nuttx/drivers/sensors/sensor.c` 的 `sensor_read()` 在 fetch 模式分支：
261	 *
262	 * @code
263	 *     nxrmutex_lock(&upper->lock);
264	 *     if (lower->ops->fetch)
265	 *       {
266	 *         if (buffer == NULL)
267	 *           {
268	 *             return -EINVAL;      // 没解锁就 return
269	 *           }
270	 * @endcode
271	 *
272	 * 一次 `read(fd, NULL, n)` 会永久泄漏该节点的递归互斥量：只有发起这次调用的
273	 * 线程还能重入，其它线程会全部阻塞在该节点的 read/open/close/ioctl 上，表现为
274	 * "这个传感器突然只对某一个线程可用"。
275	 *
276	 * 对 **push** 模式设备，`buffer == NULL` 反而是上游认可的取尺寸惯用法
277	 * （`sensor_read()` 的 `lower->persist` 分支返回 `state.esize`），只是 fetch
278	 * 分支既没沿用这个写法、又忘了解锁 —— 所以按惯用法做尺寸探测的通用代码一碰
279	 * fetch 节点就中招。本板读的 accel/gyro/baro/mag 全是 fetch 节点。
280	 *
281	 * 这里是**板级自我保护**，挡不住第三方代码直接调 `read()`；要根治得用
282	 * vela_override 替换 `drivers/sensors/sensor.c`。
283	 *
284	 * 不在生产路径上断言/panic（与 sched 那两处 sem_waitirq / sem_post 的处理
285	 * 保持一致）：返回 -EINVAL 并记一次 ERR，让自测能发现，而不是把节点搞死。
286	 *
287	 * @param fd 传感器节点 fd。
288	 * @param buf 输出缓冲；NULL 视为调用方编码错误。
289	 * @param len 期望字节数。
290	 * @return read() 的返回值；参数非法时为 -EINVAL。
291	 */
292	static ssize_t sensor_node_read(int fd, void *buf, size_t len)
293	{
294	  if (fd < 0 || buf == NULL || len == 0u)
295	    {
296	      if (!g_null_read_seen)
297	        {
298	          g_null_read_seen = true;
299	          LOGE("refuse read(fd=%d buf=%s len=%u): upstream sensor_read() "
300	               "leaks upper->lock on a NULL buffer",
301	               fd, (buf == NULL) ? "NULL" : "ok", (unsigned)len);
302	        }
303	
304	      return -EINVAL;
305	    }
306	
307	  return read(fd, buf, len);
308	}
