373	/** @brief 调用方已持有 g_lock。 */
374	static void sensor_report_fault_locked(uint8_t id, uint32_t now_ms)
375	{
376	  struct board_fault_window *win;
377	
378	  if (id >= BOARD_LANE_COUNT)
379	    {
380	      return;
381	    }
382	
383	  win = &g_fault_win[id];
384	  if (win->count == 0 ||
385	      (uint32_t)(now_ms - win->first_ms) > I2C_SENSOR_FAULT_WINDOW_MS)
386	    {
387	      win->first_ms = now_ms;
388	      win->last_ms = 0;
389	      win->count = 0;
390	    }
391	
392	  if (win->last_ms != 0 &&
393	      (uint32_t)(now_ms - win->last_ms) < I2C_SENSOR_FAULT_SPACING_MS)
394	    {
395	      return;
396	    }
397	
398	  win->last_ms = now_ms;
399	  if (win->count < UINT8_MAX)
400	    {
401	      win->count++;
402	    }
403	
404	  if (g_fault_tot[id] < UINT16_MAX)
405	    {
406	      g_fault_tot[id]++;
407	    }
408	
409	  if (win->count >= I2C_SENSOR_FAULT_THRESHOLD &&
410	      sensor_lane_may_retry(id) &&
411	      !g_lane[id].busy && !g_lane[id].pending &&
412	      (g_lane[id].retry_at == 0 ||
413	       deadline_reached(now_ms, g_lane[id].retry_at)))
414	    {
415	      g_lane[id].pending = true;
416	      g_lane[id].retry_at = 0;
417	      LOGE("request reopen %s window=%u total=%u",
418	           lane_name(id), (unsigned)win->count,
419	           (unsigned)g_fault_tot[id]);
420	    }
421	}
422	
423	static void sensor_lane_finish_locked(uint8_t id, bool ok, uint32_t now_ms)
424	{
425	  g_lane[id].busy = false;
426	  g_lane[id].pending = false;
427	  if (ok)
428	    {
429	      g_lane[id].present = true;
430	    }
431	
432	  g_stall_ms[id] = 0;
433	  if (ok)
434	    {
435	      memset(&g_fault_win[id], 0, sizeof(g_fault_win[id]));
436	      g_lane[id].retry_at = 0;
437	      LOGI("reopen %s ok, cycles=%u",
438	           lane_name(id), (unsigned)g_reopen_cycles);
439	      return;
440	    }
441	
442	  g_lane[id].retry_at = now_ms + I2C_SENSOR_RETRY_MS;
443	  LOGE("reopen %s failed, retry in %u ms",
444	       lane_name(id), (unsigned)I2C_SENSOR_RETRY_MS);
445	}
