447	/** @brief 调用方已持有 g_lock。按时间戳判断停滞，保留旧样本不算故障。 */
448	static void sensor_watch_stale_locked(uint8_t id, bool want,
449	                                      uint32_t stamp_ms, uint32_t now_ms)
450	{
451	  uint32_t *stall;
452	
453	  if (!want || g_lane[id].busy)
454	    {
455	      g_stall_ms[id] = 0;
456	      return;
457	    }
458	
459	  if (stamp_ms != 0 &&
460	      myvendor_mono_elapsed_ms(now_ms, stamp_ms) < I2C_SENSOR_STALL_MS)
461	    {
462	      g_stall_ms[id] = 0;
463	      return;
464	    }
465	
466	  stall = &g_stall_ms[id];
467	  if (*stall == 0)
468	    {
469	      *stall = now_ms;
470	      return;
471	    }
472	
473	  if ((uint32_t)(now_ms - *stall) >= I2C_SENSOR_STALL_MS)
474	    {
475	      *stall = now_ms;
476	      sensor_report_fault_locked(id, now_ms);
477	    }
478	}
