503	/**
504	 * @brief 用滤波后的毫伏得到产品百分比（回差）。
505	 *
506	 * 不因充满 IO 钉 100%：该 IO 与空闲相同（STAT 高 + DISCHRG 高），钉死会
507	 * 让 3.98 V 仍显示满电。真满电由 OCV 曲线映射到 100%。
508	 */
509	static int bat_pct_ui(int filt_mv)
510	{
511	  int pct;
512	  int charging;
513	
514	  if (filt_mv < 0)
515	    {
516	      return g_bat_pct_ui;
517	    }
518	
519	  pct = bat_pct_from_mv(filt_mv);
520	  if (pct < 0)
521	    {
522	      return g_bat_pct_ui;
523	    }
524	
525	  charging = bat_charging();
526	  if (charging && g_bat_pct_ui >= 0 && pct < g_bat_pct_ui)
527	    {
528	      return g_bat_pct_ui;
529	    }
530	
531	  if (g_bat_pct_ui < 0)
532	    {
533	      g_bat_pct_ui = pct;
534	      return pct;
535	    }
536	
537	  if (pct >= g_bat_pct_ui + BOARD_SENSOR_BAT_HYST ||
538	      pct <= g_bat_pct_ui - BOARD_SENSOR_BAT_HYST)
539	    {
540	      g_bat_pct_ui = pct;
541	    }
542	
543	  return g_bat_pct_ui;
544	}
