546	/**
547	 * @brief 充电→充满、坐在充满 IO、或旧 4.10 V KV 已到 CV 时更新满电校准。
548	 *
549	 * 电压门槛在 ctl：低于约 4.05 V 的观测直接丢弃。
550	 * 已在充满 IO、或充电且 KV 仍是旧默认（约 4.10 V）而电压已到 CV。
551	 */
552	static void bat_maybe_cal(int mv)
553	{
554	  bool edge;
555	  bool full;
556	  int stored;
557	
558	  if (mv < 0)
559	    {
560	      return;
561	    }
562	
563	  edge = eta9184_take_full_edge();
564	  full = eta9184_charge_full();
565	  if (edge || full)
566	    {
567	      myvendor_devctl_bat_full_note(mv);
568	      return;
569	    }
570	
571	  if (!bat_charging() || !myvendor_devctl_bat_full_have())
572	    {
573	      return;
574	    }
575	
576	  stored = myvendor_devctl_bat_full_mv_get();
577	  if (stored < MYVENDOR_BAT_SOC_STALE_FULL_MAX &&
578	      mv >= MYVENDOR_BAT_SOC_STALE_OBS_MIN)
579	    {
580	      myvendor_devctl_bat_full_note(mv);
581	    }
582	}
