660	/**
661	 * @brief 第一次只 TRIGGER；之后先 read 上次转换，再 TRIGGER 下一次。
662	 *
663	 * 不要在 TRIGGER 后立刻 read：FIFO 空时会 SemWait。转换结果在 FIFO 里
664	 * 等到下一拍再取，本拍只启动下一次转换。
665	 */
666	static void bat_poll(uint32_t now_ms)
667	{
668	  int fd;
669	  int ret;
670	  ssize_t n;
671	  struct adc_msg_s msg;
672	  int mv;
673	
674	  pthread_mutex_lock(&g_lock);
675	  fd = g_adc_fd;
676	  pthread_mutex_unlock(&g_lock);
677	  if (fd < 0)
678	    {
679	      return;
680	    }
681	
682	  if (g_adc_conv)
683	    {
684	      n = read(fd, &msg, sizeof(msg));
685	      if (n != (ssize_t)sizeof(msg))
686	        {
687	          bat_fail_fd(fd);
688	          return;
689	        }
690	
691	      mv = (int)msg.am_data;
692	      if (g_bat_ema < 0)
693	        {
694	          g_bat_ema = mv;
695	        }
696	      else
697	        {
698	          g_bat_ema += (mv - g_bat_ema) / BOARD_SENSOR_BAT_EMA;
699	        }
700	
701	      bat_maybe_cal(g_bat_ema);
702	      (void)bat_pct_ui(g_bat_ema);
703	      bat_publish(mv, g_bat_pct_ui, now_ms);
704	    }
705	  else
706	    {
707	      (void)ioctl(fd, ANIOC_RESET_FIFO, 0);
708	    }
709	
710	  ret = ioctl(fd, ANIOC_TRIGGER, 0);
711	  if (ret < 0)
712	    {
713	      bat_fail_fd(fd);
714	      return;
715	    }
716	
717	  g_adc_conv = true;
718	}
