783	static void sensor_accel_lp_locked(float x, float y, float z)
784	{
785	  float n = sqrtf(x * x + y * y + z * z);
786	
787	  if (n < I2C_SENSOR_G_MIN || n > I2C_SENSOR_G_MAX)
788	    {
789	      return;
790	    }
791	
792	  if (!g_accel_f_have)
793	    {
794	      g_accel_f.x = x;
795	      g_accel_f.y = y;
796	      g_accel_f.z = z;
797	      g_accel_f.valid = true;
798	      g_accel_f_have = true;
799	      return;
800	    }
801	
802	  g_accel_f.x += I2C_SENSOR_ACCEL_LP_A * (x - g_accel_f.x);
803	  g_accel_f.y += I2C_SENSOR_ACCEL_LP_A * (y - g_accel_f.y);
804	  g_accel_f.z += I2C_SENSOR_ACCEL_LP_A * (z - g_accel_f.z);
805	}
