808	{
809	  int accel_fd;
810	  int gyro_fd;
811	  struct sensor_accel accel;
812	  struct sensor_gyro gyro;
813	  enum i2c_read_kind accel_kind = I2C_READ_EMPTY;
814	  enum i2c_read_kind gyro_kind = I2C_READ_EMPTY;
815	  ssize_t n;
816	
817	  pthread_mutex_lock(&g_lock);
818	  accel_fd = g_accel_fd;
819	  gyro_fd  = g_gyro_fd;
820	  pthread_mutex_unlock(&g_lock);
821	  if (accel_fd < 0 || gyro_fd < 0)
822	    {
823	      return;
824	    }
825	
826	  n = sensor_node_read(accel_fd, &accel, sizeof(accel));
827	  accel_kind = sensor_classify_read(n, sizeof(accel));
828	  n = sensor_node_read(gyro_fd, &gyro, sizeof(gyro));
829	  gyro_kind = sensor_classify_read(n, sizeof(gyro));
830	
831	  pthread_mutex_lock(&g_lock);
832	  if (accel_kind == I2C_READ_DATA)
833	    {
834	      g_accel.valid = true;
835	      g_accel.x = accel.x;
836	      g_accel.y = accel.y;
837	      g_accel.z = accel.z;
838	      g_accel_ms = now_ms;
839	      sensor_accel_lp_locked(accel.x, accel.y, accel.z);
840	    }
841	  else if (accel_kind == I2C_READ_ERR)
842	    {
843	      sensor_report_fault_locked(BOARD_LANE_IMU, now_ms);
844	    }
845	
846	  if (gyro_kind == I2C_READ_DATA)
847	    {
848	      g_gyro.valid = true;
849	      g_gyro.x = gyro.x;
850	      g_gyro.y = gyro.y;
851	      g_gyro.z = gyro.z;
852	      g_gyro_ms = now_ms;
853	    }
854	  else if (gyro_kind == I2C_READ_ERR)
855	    {
856	      sensor_report_fault_locked(BOARD_LANE_IMU, now_ms);
857	    }
858	
859	  pthread_mutex_unlock(&g_lock);
860	}
