1143	/** @brief close/open 走 I2C activate，必须在 g_lock 外执行。只动这一路。 */
1144	static void sensor_reopen_lane(uint8_t id, uint32_t now_ms)
1145	{
1146	  const struct board_lane_ops *ops;
1147	  bool ok = false;
1148	
1149	  if (id >= BOARD_LANE_COUNT)
1150	    {
1151	      return;
1152	    }
1153	
1154	  ops = &g_ops[id];
1155	  if (ops->open == NULL || ops->take_locked == NULL ||
1156	      ops->close == NULL || ops->install_locked == NULL)
1157	    {
1158	      return;
1159	    }
1160	
1161	  pthread_mutex_lock(&g_lock);
1162	  if (g_lane[id].busy)
1163	    {
1164	      pthread_mutex_unlock(&g_lock);
1165	      return;
1166	    }
1167	
1168	  g_lane[id].busy = true;
1169	  g_lane[id].pending = false;
1170	  if (g_reopen_cycles < UINT16_MAX)
1171	    {
1172	      g_reopen_cycles++;
1173	    }
1174	
1175	  if (ops->reopen_begin_locked != NULL)
1176	    {
1177	      ops->reopen_begin_locked();
1178	    }
1179	
1180	  ops->take_locked();
1181	  pthread_mutex_unlock(&g_lock);
1182	
1183	  LOGI("reopen %s begin cycles=%u",
1184	       lane_name(id), (unsigned)g_reopen_cycles);
1185	
1186	  ops->close();
1187	  usleep(I2C_SENSOR_REOPEN_GAP_US);
1188	  if (ops->recover_hw != NULL)
1189	    {
1190	      ops->recover_hw();
1191	    }
1192	
1193	  ok = (ops->open() == 0);
1194	  pthread_mutex_lock(&g_lock);
1195	  ops->install_locked(ok);
1196	  if (!ok)
1197	    {
1198	      pthread_mutex_unlock(&g_lock);
1199	      ops->close();
1200	      pthread_mutex_lock(&g_lock);
1201	    }
1202	
1203	  sensor_lane_finish_locked(id, ok, now_ms);
1204	  pthread_mutex_unlock(&g_lock);
1205	}
