1263	static void *sensor_thread(void *arg)
1264	{
1265	  (void)arg;
1266	
1267	  sensor_open_all();
1268	  pthread_mutex_lock(&g_lock);
1269	  g_running = true;
1270	  pthread_mutex_unlock(&g_lock);
1271	
1272	  while (g_running)
1273	    {
1274	      uint32_t now = sensor_now_ms();
1275	      int reopen_id = -1;
1276	      uint8_t i;
1277	
1278	      for (i = 0; i < BOARD_LANE_COUNT; i++)
1279	        {
1280	          if (g_ops[i].poll == NULL || g_ops[i].period_ms == 0 ||
1281	              g_lane[i].busy)
1282	            {
1283	              continue;
1284	            }
1285	
1286	          if (g_lane[i].last_ms != 0 &&
1287	              (uint32_t)(now - g_lane[i].last_ms) < g_ops[i].period_ms)
1288	            {
1289	              continue;
1290	            }
1291	
1292	          g_ops[i].poll(now);
1293	          g_lane[i].last_ms = now;
1294	        }
1295	
1296	      pthread_mutex_lock(&g_lock);
1297	      sensor_supervisor_tick_locked(now);
1298	      for (i = 0; i < BOARD_LANE_COUNT; i++)
1299	        {
1300	          if (g_lane[i].pending && !g_lane[i].busy)
1301	            {
1302	              reopen_id = (int)i;
1303	              break;
1304	            }
1305	        }
1306	
1307	      pthread_mutex_unlock(&g_lock);
1308	
1309	      if (reopen_id >= 0)
1310	        {
1311	          sensor_reopen_lane((uint8_t)reopen_id, now);
1312	        }
1313	
1314	      usleep(I2C_SENSOR_LOOP_MS * 1000);
1315	    }
1316	
1317	  sensor_close_all();
1318	  return NULL;
1319	}
