111	/** @brief 状态变化则通知 upper-half。 */
112	static void sf32lb52_button_notify(FAR struct sf32lb52_btnlower_s *priv)
113	{
114	    btn_buttonset_t sample;
115	    btn_handler_t handler;
116	    FAR void *arg;
117	    irqstate_t flags;
118	
119	    sample = sf32lb52_button_readset();
120	    if (sample == priv->last_sample) {
121	        return;
122	    }
123	
124	    /* handler 与 arg 必须在同一临界区里成对取出：enable 侧会在临界区内把两个
125	     * 一起置 NULL。以前是分两次裸读，中间被 enable 插进来就会用 NULL 调用
126	     * handler —— btn_interrupt 直接解引用 arg。回调在临界区外调用，避免带着
127	     * 关中断去跑上层代码。 */
128	    flags = up_irq_save();
129	    priv->last_sample = sample;
130	    handler = priv->handler;
131	    arg     = priv->arg;
132	    up_irq_restore(flags);
133	
134	    if (handler != NULL && arg != NULL) {
135	        handler(&priv->lower, arg);
136	    }
137	}
