139	/** @brief 板级轮询线程：只在线程上下文读键。 */
140	static int sf32lb52_button_poll_task(int argc, FAR char *argv[])
141	{
142	    FAR struct sf32lb52_btnlower_s *priv = &g_btnlower;
143	
144	    (void)argc;
145	    (void)argv;
146	
147	    for (;;) {
148	        if (priv->poll_enabled) {
149	            sf32lb52_button_notify(priv);
150	        }
151	
152	        usleep(SF32LB52_BUTTON_POLL_MS * 1000);
153	    }
154	
155	    return 0;
156	}
