176	/** @brief 使能/禁用轮询并挂接 handler。 */
177	static void sf32lb52_btn_enable(FAR const struct btn_lowerhalf_s *lower,
178	                                btn_buttonset_t press,
179	                                btn_buttonset_t release,
180	                                btn_handler_t handler,
181	                                FAR void *arg)
182	{
183	    FAR struct sf32lb52_btnlower_s *priv = (FAR struct sf32lb52_btnlower_s *)lower;
184	    btn_buttonset_t either = press | release;
185	    irqstate_t flags;
186	    int ret;
187	
188	    /* handler/arg 成对更新，与 sf32lb52_button_notify 的成对读取用同一临界区
189	     * 互斥；否则轮询线程可能取到"旧 handler + NULL arg"。 */
190	    if (either == 0 || handler == NULL) {
191	        flags = up_irq_save();
192	        priv->poll_enabled = false;
193	        priv->handler = NULL;
194	        priv->arg = NULL;
195	        up_irq_restore(flags);
196	        return;
197	    }
198	
199	    {
200	        btn_buttonset_t snap = sf32lb52_button_readset();
201	
202	        flags = up_irq_save();
203	        priv->handler = handler;
204	        priv->arg = arg;
205	        priv->last_sample = snap;
206	        priv->poll_enabled = true;
207	        up_irq_restore(flags);
208	    }
209	
210	    if (priv->poll_tid <= 0) {
211	        ret = kthread_create_with_stack("btn_poll",
212	                                        SF32LB52_BUTTON_POLL_PRIO,
213	                                        g_btn_poll_stack,
214	                                        sizeof(g_btn_poll_stack),
215	                                        sf32lb52_button_poll_task, NULL);
216	        if (ret > 0) {
217	            priv->poll_tid = ret;
218	        }
219	    }
220	}
