int sf32lb52_bmi270_recover(void)
{
  int ret;

  if (g_bmi_i2c == NULL)
    {
      syslog(LOG_ERR, "bmi270: recover skipped, bus unknown\n");
      return -ENODEV;
    }

  if (!g_bmi_registered)
    {
      syslog(LOG_WARNING, "bmi270: recover register (was missing)\n");
      ret = sf32lb52_bmi270_register(g_bmi_devno, g_bmi_i2c, g_bmi_addr);
      if (ret < 0)
        {
          syslog(LOG_ERR, "bmi270: recover register failed: %d\n", ret);
        }

      return ret;
    }

  syslog(LOG_INFO, "bmi270: recover softreset + init_seq\n");
  bmi270_softreset(&g_bmi_dev->priv[BMI270_ACCEL_IDX].base);
  ret = bmi270_init_seq(&g_bmi_dev->priv[BMI270_ACCEL_IDX].base);
  if (ret < 0)
    {
      syslog(LOG_ERR, "bmi270: recover init_seq failed: %d\n", ret);
      return ret;
