static clock_t wdt_now(void)
{
  return clock_systime_ticks();
}

static uint32_t wdt_age_ms(clock_t last)
{
  clock_t now = wdt_now();
  clock_t dt = now - last;

  /* 滴答回退时 unsigned 下溢，会误判心跳过期而停喂狗。 */
  if (dt > ((clock_t)-1 / 2))
